from __future__ import absolute_import
import time
import re
from hran_radio.radio_connection.telnet_interface import TelnetConnection
from hran_radio.radio_output_parser.gaia_parser import FrontEndGainGAIA, TxStatGAIA, RxStatGAIA, \
    TxPowerGAIA, RxPowerGAIA
from .radio_base import RadioBase
from hran_radio.exceptions import RadioDidNotRespond
from robot.api import logger


class RadioGAIA(RadioBase):
    def __init__(self, radio_ip, system_module_ip, master_system_module_ip):
        super(RadioGAIA, self).__init__(
            radio_ip, system_module_ip, master_system_module_ip
        )
        self.radio_connection = TelnetConnection(
            self._radio_ip, self._sm_ip, self._msm_ip, "2323"
        )
        self.release = self.radio_connection.get_smod_release()

    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
        tx_power = self._get_raw_tx_power()
        tx_stat = self._get_raw_tx_stat()
        logger.debug(tx_power.parse_tx_power())
        logger.debug(tx_stat.resource_per_antenna)
        return self._parse_tx_power(
            tx_power.parse_tx_power(), tx_stat.resource_per_antenna
        )

    def all_rx_power(self):
        """
        Return all rx power in format {rx: power}.

        :return: rx power
        :rtype: dict
        """
        rx_power = self._get_raw_rx_power()
        rx_stat = self._get_raw_rx_stat()
        logger.debug(rx_power.parse_rx_power())
        logger.debug(rx_stat.resource_per_antenna)
        return self._parse_rx_power(
            rx_power.parse_rx_power()
        )

    def lte_tx_power(self):
        """
        Return tx power for LTE technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("LTE")

    def wcdma_tx_power(self):
        """
        Return tx power for WCDMA technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("WCDMA")

    def gsm_tx_power(self):
        """
        Return tx power for GSM technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("GSM")

    def front_end_gain(self, antenna_number):
        """
        Return front end gain for antenna.

        :return: front end gain
        :rtype: int
        """
        antenna_dict = {1: "1 1", 2: "1 2", 3: "2 1", 4: "2 2", 5: "3 1", 6: "3 2"}
        raw_output = self.run_radio_command(
            "frontEnd feGetLnaGain {}".format(antenna_dict[int(antenna_number)])
        )
        front_end_gain = FrontEndGainGAIA(raw_output)
        return front_end_gain.parse_front_end_gain()

    def tx_carrier_data(self):
        """
        Return tx carrier data.

        :return: tx carrier data
        :rtype: dict
        """
        tx_stat = self._get_raw_tx_stat()
        return tx_stat.parse_carrier_by_antenna()

    def rx_carrier_data(self):
        """
        Return rx carrier data.

        :return: rx carrier data
        :rtype: dict
        """
        raw_output = self.run_radio_command("rfctrl rxStat")
        tx_stat = RxStatGAIA(raw_output)
        return tx_stat.parse_carrier_by_antenna()

    def _parse_tx_power(self, tx_power_dict, tx_stat_dict):
        tx_output = {}
        for antenna, resources in tx_stat_dict.items():
            for resource in resources:
                for resource_tx in tx_power_dict["resource"]:
                    if re.match(
                            r"%s/\d{2}|\d{1,2}/%s$" % (resource, resource), resource_tx
                    ):
                        tx_output.setdefault(
                            "{}/{}".format(antenna, resource),
                            tx_power_dict[antenna][
                                tx_power_dict["resource"].index(resource_tx)
                            ],
                        )
        return self._set_off_when_no_power(tx_output)

    def _parse_rx_power(self, rx_power_dict):
        rx_output = {}
        for antenna, rx_powers in rx_power_dict.items():
            for rx_power in rx_powers:
                resource_value = re.match(r"(?P<power>-?\d*.\d)*\[(?P<resource>.*)]", rx_power)
                if resource_value:
                    rx_output.setdefault("{}/{}".format(antenna, int(resource_value.group("resource"))),
                                         resource_value.group("power"))
        return self._set_off_when_no_power(rx_output)

    def _get_raw_tx_stat(self):
        raw_tx_stat = self.run_radio_command("rfctrl txStat")
        return TxStatGAIA(raw_tx_stat)

    def _get_raw_rx_stat(self):
        raw_tx_stat = self.run_radio_command("rfctrl rxStat")
        return RxStatGAIA(raw_tx_stat)

    def _get_raw_tx_power(self):
        for request in range(5):
            check_power_pattern = re.compile(
                r"IMPORTANT NOTICE: resource and NCO index has been changed to 0 based"
            )
            raw_tx_power = self.run_radio_command("rfctrl txPower")
            if check_power_pattern.search(raw_tx_power):
                return TxPowerGAIA(raw_tx_power)
            time.sleep(10)
        raise RadioDidNotRespond("rfctrl txPower")

    def _get_raw_rx_power(self):
        for request in range(5):
            check_power_pattern = re.compile(
                r"IMPORTANT NOTICE: resource and NCO index has been changed to 0 based"
            )
            raw_rx_power = self.run_radio_command("rfctrl rxPower")
            if check_power_pattern.search(raw_rx_power):
                return RxPowerGAIA(raw_rx_power)
            time.sleep(10)
        raise RadioDidNotRespond("rfctrl rxPower")

    def _get_tx_power_for(self, technology):
        tx_power = self._get_raw_tx_power()
        tx_stat = self._get_raw_tx_stat()
        tx_power_dict = self._parse_tx_power(
            tx_power.parse_tx_power(), tx_stat.resource_per_antenna
        )
        tx_tech = tx_stat.get_tx_per_technology()
        return self._group_tx_per_tech(tx_power_dict, tx_tech, technology)

    @staticmethod
    def _set_off_when_no_power(tx_dict):
        for tx, power in tx_dict.items():
            if power == "n.a":
                tx_dict[tx] = "OFF"
        return tx_dict

    @staticmethod
    def _group_tx_per_tech(tx_power_dict, tx_tech, technology):
        output_dict = {}
        for tx, power in tx_power_dict.items():
            if re.match(technology, tx_tech[tx]):
                output_dict.setdefault(tx, power)
        return output_dict
